export type CompileMandate = {
    /**
     * The shopping request in natural language, at most 2000 UTF-16 code units.
     */
    prompt: string;
    /**
     * The passkey that will sign the mandate; defaults to the most recent one.
     */
    credentialId?: string;
    /**
     * Whether the user is present at checkout (`immediate`) or not (`autonomous`).
     */
    mode?: 'immediate' | 'autonomous';
};

export type Countersigned = {
    purchaseId: string;
    /**
     * `degraded` when leg B was unreachable and only leg A signed.
     */
    mode: '2of2' | 'degraded';
    decision: 'allow' | 'deny';
    /**
     * The EIP-712 `Countersign` message, as decimal strings.
     */
    countersign: {
        [key: string]: string;
    };
    digest: string;
    signatures: {
        tdx: string;
        nitro: string | null;
    };
    signers: {
        tdx: string;
        nitro: string | null;
    };
    /**
     * The `keelson.eval/1` trace both legs signed over.
     */
    trace?: unknown;
    approval?: OnceApproval;
    /**
     * `CAPTURED` once logged, covered and captured; `FAILED` with `failure` when a step refused; `COUNTERSIGNED`, `LOGGED` or `COVERED` while a step is pending; `DENIED` for a DENY.
     */
    state?: string;
    /**
     * The leaf's index in the Alibi log.
     */
    logIndex?: string;
    /**
     * The `lockCoverage` transaction of the operator's bond.
     */
    coverage?: {
        chainId: number;
        txHash: string | null;
    };
    /**
     * The PayPal capture of the countersigned amount.
     */
    capture?: {
        id: string;
        invoiceId: string;
        status: string | null;
    };
    /**
     * The step that failed and why; nothing was captured.
     */
    failure?: {
        step: string;
        reason: string;
    };
    /**
     * For a `DENIED` cart, the mandate fields whose check failed.
     */
    blocked?: Array<string>;
    /**
     * For a `DENIED` cart, each failed field with what the mandate allowed and what the cart had, as text.
     */
    reasons?: Array<{
        field: string;
        mandate: string | null;
        cart: string | null;
    }>;
    /**
     * For a purchase the engine checked, each mandate field with what the mandate allowed, what the cart had and whether it held.
     */
    checks?: Array<{
        field: string;
        mandate: string | null;
        cart: string | null;
        pass: boolean;
    }>;
    /**
     * A card purchase: its single-use card (never its number) and every authorization the card network sent it, with both legs' decision. `CAPTURED` once the merchant's capture settles.
     */
    card?: {
        issuer: string;
        lastFour: string;
        state: string;
        expiresAt: string;
        controls: {
            [key: string]: unknown;
        };
        settledMinor: string | null;
        /**
         * Chargebacks filed through the card issuer over this purchase.
         */
        chargebacks: Array<{
            [key: string]: unknown;
        }>;
        /**
         * The most a bond claim over this purchase may pay: the settled amount less what chargebacks returned; 0 while one is open.
         */
        bondClaimMinor: string;
        authorizations: Array<{
            id: string;
            amountMinor: string;
            currency: string;
            mcc: string;
            merchantName: string;
            merchantCountry: string;
            approved: boolean;
            failedMask: number;
            reason: string | null;
            legs: {
                tdx: boolean;
                nitro: boolean;
            };
            latencyMs: number;
            at: string;
        }>;
    };
    /**
     * A purchase the buyer pays at the store's own checkout: the store's origin and the PayPal transaction id once the agent recorded it. Never covered nor captured.
     */
    live?: {
        store: string;
        transactionId: string | null;
    };
};

/**
 * On a deny for a cart over the mandate's amount or outside its merchants: the user was asked to approve this cart once. Poll `POST /v1/connections/token` with its `device_code`; the answer is a single-purchase mandate for exactly this cart.
 */
export type OnceApproval = {
    /**
     * Absent when the user is already being asked about this cart: keep polling the device code you were given then.
     */
    device_code?: string;
    user_code: string;
    verification_uri: string;
    verification_uri_complete: string;
    expires_in: number;
    interval: number;
    /**
     * Read the request's state with `GET /v1/connections/requests/{id}`.
     */
    request_id: string;
};

export type CountersignRequest = {
    /**
     * The PayPal authorization that holds the mandate's funds, or this request's own hold when the mandate holds each purchase separately; leg A reads it. Absent for a card mandate, whose purchase is paid with a single-use card issued after the ALLOW.
     */
    authorizationId?: string;
    /**
     * The open mandate closed by the agent's key binding over the request and cart. Required, except of an app acting for a user under a mandate of Keelson's hosted operator, which sends `mandateId` instead.
     */
    closedMandate?: string;
    /**
     * Only for an app acting for a user (`purchases:write`) under a mandate of Keelson's hosted operator that the user approved for it: Keelson closes the mandate with the hosted operator's key over `requestId` and this cart.
     */
    mandateId?: string;
    /**
     * With `mandateId`: the request ULID the closed mandate binds, and the purchase's id; a new one when left out.
     */
    requestId?: string;
    cart: Cart;
    /**
     * The PayPal purchase unit the cart is checked against: `{amount}`, the checkout total the buyer pays as a PayPal Orders v2 amount, whose `breakdown` has the `item_total` of the cart's lines and, when the checkout charges them, `tax_total`, `shipping` and `discount`. Keelson countersigns `amount.value`, which must be `item_total + tax_total + shipping − discount`, and checks it against the mandate's budget. `handling`, `insurance` and `shipping_discount` are refused: fold them into `shipping`.
     */
    unit: {
        [key: string]: unknown;
    };
    /**
     * Evidence sources per field. `channel3:` sources are refused here: the API adds them from the observation stored in the evidence.
     */
    evidence?: {
        [key: string]: Array<string>;
    };
    /**
     * The root of the evidence stored with `POST /v1/evidence` for this mandate.
     */
    evidenceRoot: string;
    /**
     * Only when the buyer pays at the store's own checkout with their own PayPal account: Keelson countersigns and logs the purchase and issues its Alibi, and neither covers nor captures it. Its Alibi is public once the PayPal transaction is recorded. The agent's pay click waits for an ALLOW; the agent then records PayPal's transaction id with `PUT /v1/purchases/{id}/paypal-transaction`.
     */
    live?: {
        /**
         * The store's origin: the origin of the website the mandate allows for the cart's merchant.
         */
        store: string;
    };
    /**
     * Only when the user asked to buy the same cart again: the id of the latest purchase of this cart under the mandate. Not needed once that purchase was denied or failed before capture, or was captured more than ten minutes ago. A retry after a lost answer never sends it: the `409 purchase-exists` answer names the purchase already made.
     */
    repeatOf?: string;
};

