export type AnonymousMandate = {
    /**
     * The passkey challenge `M` the user signed.
     */
    mandate_hash: string;
    /**
     * `C_m`, the commitment the mandate names.
     */
    mandate_commitment: string;
    /**
     * The registered-user tree the signer is a leaf of when the proof was made.
     */
    user_set_root: string;
    /**
     * The UltraHonk proof bytes, standard base64.
     */
    proof: string;
    /**
     * `C_m, M mod r, user_set_root, SHA-256("keelson.finance")`: the calldata of `verify(bytes,bytes32[])`.
     */
    public_inputs: Array<string>;
    /**
     * The deployed verifier that accepts the proof in an `eth_call`. It checks the proof only: `public_inputs` must also be the countersign's `C_m` and `M`, Keelson's RP ID hash, and a root published in `RegisteredUserSet`, whose `verify` checks all of it.
     */
    verifier?: {
        chain_id: number;
        address: string;
    };
};

export type AnonymousPurchase = {
    user_set_root: string;
    /**
     * The UltraHonk proof bytes, standard base64.
     */
    proof: string;
    /**
     * C1's `C_m, amount, currency, category, merchant_id, now, cart_hash, operator_id`, then `M mod r` and `user_set_root`: the calldata of `verify(bytes,bytes32[])`.
     */
    public_inputs: Array<string>;
    /**
     * The deployed verifier that accepts the proof in an `eth_call`. It checks the proof only: `public_inputs` must also be the countersign's and the root one `GET /v1/user-set/roots/{root}` lists.
     */
    verifier?: {
        chain_id: number;
        address: string;
    };
    /**
     * The Arbitrum Sepolia transaction that published `user_set_root` to `RegisteredUserSet`, once it is confirmed.
     */
    root_tx?: string;
};

export type UserSetRoot = {
    root: string;
    /**
     * Registered users when the tree had this root.
     */
    size: number;
    created_at: string;
};

export type DisputeStatus = {
    dispute_id: string;
    purchase_id: string;
    state: 'OPEN' | 'ATTRIBUTED' | 'RESOLVED';
    /**
     * PayPal's `dispute_reason`.
     */
    reason: string;
    /**
     * When Keelson received the dispute's first webhook or poll.
     */
    received_at: string | null;
    attributed_at: string | null;
    /**
     * From `received_at` to `attributed_at`; null while the dispute is open.
     */
    elapsed_ms: number | null;
    liable: 'operator' | 'keelson' | 'merchant' | 'user' | null;
    /**
     * The parties a verdict can make pay: the operator's bond, Keelson's reserve, or the merchant through PayPal.
     */
    parties: Array<{
        party: 'operator' | 'keelson' | 'merchant';
        liable: boolean;
    }>;
    verdict: {
        rule: string;
        digest: string;
        chain_id: number;
        message: {
            [key: string]: string;
        };
        signatures: Array<{
            tee: number;
            signer: string;
            signature: string;
        }>;
        facts: {
            [key: string]: string | boolean;
        };
    } | null;
    settlement: {
        /**
         * `pyusd`: the payee the verdict names is the merchant. `paypal`: it is Keelson's treasury, which pays the merchant a PayPal Payout.
         */
        rail: 'pyusd' | 'paypal';
        /**
         * `queued`: the slash waits out the veto window until `ready_at`. `claimable`: the PYUSD transfer failed and waits as a claim. Null until the chain answered; always null when neither the operator nor Keelson is liable.
         */
        outcome: 'paid' | 'queued' | 'claimable' | 'failed' | null;
        /**
         * The contract error that refused the settlement on chain: of a `failed` one, or of one Keelson's treasury paid instead.
         */
        failure: string | null;
        /**
         * `chain`: the operator's bond or Keelson's reserve paid. `violation-pool`: the operator's `ViolationBondPool` deposit paid the merchant on a court's conviction, with no verdict. `treasury`: the chain refused a verdict that still holds (its window or deadline had passed), so Keelson's treasury pays the payee itself, PYUSD on chain or a PayPal Payout; the settlement is paid once `outcome` is `paid`.
         */
        paid_by: 'chain' | 'treasury' | 'violation-pool' | null;
        /**
         * The buyer's PayPal refund; its `custom_id` is the verdict's `ksv1.` reference.
         */
        refund_id: string | null;
        tx_hash: string | null;
        explorer_url: string | null;
        ready_at: string | null;
        payout_batch_id: string | null;
        payout_status: string | null;
        settled_at: string | null;
    } | null;
    /**
     * What Keelson sent PayPal for the party at fault. The action and the evidence types follow from the rule; a model only drafts the text.
     */
    responses: Array<{
        action: 'provide_evidence' | 'send_message' | 'accept_claim';
        /**
         * PayPal's lifecycle stage when it was sent.
         */
        stage: string;
        evidence_types: Array<string>;
        /**
         * `model` when the statement was drafted with citations; `template` when the rule's fixed statement was sent. Null for an accepted claim.
         */
        drafted_by: 'model' | 'template' | null;
        /**
         * How many passages of the Alibi and the verdict the statement cites. The statement itself is not public: it quotes the purchase's Alibi.
         */
        citations: number;
        sent_at: string;
    }>;
    amber: AmberCase;
};

/**
 * What the operator attested about the item it bought, and whether it was proven false. Null when the purchase carries no attestation (a cart of several lines, or bought before attestations).
 */
export type AmberCase = {
    /**
     * The `amberCommitment` the operator signed into the coverage: Poseidon2 over the product page, the fields below and a salt.
     */
    commitment: string;
    /**
     * What the operator attested. Null on the public dispute read: what was bought stays with the consoles.
     */
    attested: {
        /**
         * The store's JSON page for the SKU.
         */
        url: string;
        sku: string;
        size: string;
        color: string;
        unit_minor: string;
        returns_free: boolean;
    } | null;
    /**
     * `AmberContradictionCourt`'s conviction on Arbitrum Sepolia: a C2b proof that the store's own answer, notarized by leg A, holds another value of `field`. Null while there is none.
     */
    conviction: {
        field: 'size' | 'color' | 'unit_price' | 'returns_free';
        /**
         * What the operator attested of the field, which the store's answer contradicts. Null on the public dispute read.
         */
        attested_value: string | null;
        proven_at: string;
        /**
         * The EIP-712 digest of the `WebFact` leg A signed over the store's answer.
         */
        web_fact_digest: string;
        captured_at: string | null;
        tx_hash: string;
        explorer_url: string;
        proof: {
            bytes: number;
            /**
             * keccak256 of the proof.
             */
            hash: string;
            /**
             * `range_hi, range_lo, amber_commitment, product, field_id`, as the court gave the verifier.
             */
            public_inputs: Array<string>;
        } | null;
    } | null;
} | null;

