/**
 * An operator's trust grade, premium and minimum bond. Amounts are US cents. The red-team campaigns set the prior of the incident rate; the operator's covered purchases and the verdicts with it at fault update it in closed form; a seeded Monte Carlo of the aggregate loss over the next 30 days prices the premium and the bond.
 */
export type TrustGrade = {
    v: 'keelson.grade/1';
    agentId: string;
    /**
     * From the one-sided 95 % credible upper bound of the incident rate: A ≤ 1 %, B ≤ 2 %, C ≤ 5 %, D ≤ 10 %, F above.
     */
    grade: 'A' | 'B' | 'C' | 'D' | 'F';
    computedAt: string;
    calibration: {
        id: string;
        at: string;
        /**
         * The red-team campaigns pooled.
         */
        campaigns: Array<string>;
        /**
         * The prior's mean, ASR × escape + amber.
         */
        mu_ppm: number;
        /**
         * The prior's strength, by the method of moments.
         */
        kappa: number;
    };
    evidence: {
        coverages: number;
        /**
         * Verdicts with the operator at fault: what the grade counts.
         */
        incidents: {
            total: number;
            /**
             * Paid from the operator's bond.
             */
            slashes: number;
            /**
             * Paid from its `ViolationBondPool` deposit.
             */
            pool: number;
            /**
             * Paid by Keelson's treasury instead.
             */
            uncollected: number;
            /**
             * Not settled yet.
             */
            pending: number;
        };
    };
    /**
     * Keelson's own faults on the operator's coverages, paid by its reserve. Not in the grade.
     */
    reserve: {
        warranties: number;
    };
    frequency: {
        alpha: number;
        beta: number;
        credibility_ppm: number;
        mean_ppm: number;
        upper95_ppm: number;
    };
    severity: {
        meanMinor: number;
        maxMinor: number;
        lossRatio_ppm: number;
    };
    loss: {
        horizon: number;
        scenarios: number;
        expectedMinor: number;
        var99Minor: number;
        es99Minor: number;
        var995Minor: number;
    };
    premium: {
        /**
         * Charged on each new coverage, in `lockCoverage`.
         */
        bps: number;
        modelBps: number;
        floorBps: number;
        theta: number;
        costOfCapital: number;
    };
    bond: {
        requiredMinor: number;
    };
    computeMs: number;
};

