export type GetStatusData = {
    body?: never;
    path?: never;
    query?: never;
    url: '/status';
};

export type GetStatusResponses = {
    /**
     * Status of the service and its dependencies; always 200
     */
    200: {
        status: 'ok' | 'degraded';
        dependencies: {
            db: 'up' | 'down';
            kv: 'up' | 'down';
            teeA?: 'up' | 'down';
            teeB?: 'up' | 'down';
            relayer?: {
                status: 'up' | 'down' | 'degraded';
                chains: Array<{
                    chainId: number;
                    status: 'up' | 'down' | 'degraded';
                    address: string;
                    balanceWei?: string;
                    nextNonce?: string;
                    pending: number;
                    baseFeeWei?: string;
                }>;
            };
            log?: {
                status: 'up' | 'down';
                origins: Array<{
                    origin: string;
                    size: number;
                    checkpointAgeMs: number;
                }>;
            };
            paypal?: {
                status: 'up' | 'down';
                environment: 'sandbox' | 'production';
            };
            webhooks?: {
                status: 'up' | 'down';
                lastWebhookAgeMs?: number;
                lastPollAgeMs?: number;
            };
            chainEvents?: {
                status: 'up' | 'down';
                finalizedBlock?: string;
                reconciledAgeMs?: number;
            };
            anchor?: {
                status: 'up' | 'down';
                environment: 'arbitrum-sepolia';
                size?: string;
                anchoredAgeMs?: number;
            };
        };
        rpc: {
            calls: Array<{
                provider: string;
                method: string;
                calls: number;
            }>;
        };
        version: string;
    };
};

export type GetStatusResponse = GetStatusResponses[keyof GetStatusResponses];

export type StreamEventsData = {
    body?: never;
    headers?: {
        'last-event-id'?: string;
    };
    path?: never;
    query: {
        /**
         * `public:<name>`, or the caller's own namespace `<base64url(kind:subject)>` with an optional `:<suffix>`.
         */
        channel: string;
    };
    url: '/v1/events';
};

export type StreamEventsErrors = {
    /**
     * Invalid channel or Last-Event-ID
     */
    400: Problem;
    /**
     * Not authenticated
     */
    401: Problem;
    /**
     * The channel belongs to another principal
     */
    403: Problem;
    /**
     * Too many concurrent streams for this principal
     */
    429: Problem;
};

export type StreamEventsError = StreamEventsErrors[keyof StreamEventsErrors];

export type StreamEventsResponses = {
    /**
     * An event stream; each event carries the row id, the channel and a JSON payload
     */
    200: string;
};

export type StreamEventsResponse = StreamEventsResponses[keyof StreamEventsResponses];

